const current=load("current_packet");
const prior=load("repair").inference;
const r=JSON.parse(JSON.stringify(current.inference));
r.rules=JSON.parse(JSON.stringify(prior.rules));
r.locals=JSON.parse(JSON.stringify(prior.locals));
r.argument[1]=JSON.parse(JSON.stringify(prior.argument[1]));
r.argument[2]=JSON.parse(JSON.stringify(prior.argument[2]));
r.argument[2].text=r.argument[2].text.replace("To justify the same identity and the ordinary suprema for rough H^sigma inputs, first use E003 at grid base t_0=0 and beta=1+sigma.","For the current positive tau choose E003's auxiliary source grid with step count 1 and step index 0. The count is a positive integer and the index satisfies 0<=0<1, so its source base is 0*tau=0 and its step is [0,tau]. The auxiliary grid horizon is tau, with no condition involving the problem parameter T or the arbitrary target base a. To justify the same identity and the ordinary suprema for rough H^sigma inputs, first use E003 at this explicitly admissible base zero and beta=1+sigma.");
r.applications=JSON.parse(JSON.stringify(prior.applications));
for (const id of ["A003","A004","A005"]){
 const a=r.applications.find(x=>x.id===id);
 a.bindings+=" Choose the source grid parameters Lsrc=1 and nsrc=0; its defining formula gives source base 0*tau=0 and step [0,tau].";
 a.hypothesis_checks[0]+=" The positive integer count 1 and integer index 0 satisfy 0<=0<1, so E003 explicitly supplies this base-zero step for every tau>0. Its auxiliary horizon tau need not equal T; there is no grid condition on the target base a after conjugation.";
}
store("current_repair",{inference:r});
text(await tools.check_draft({artifact:{inference:r}}));
